mapper.select:
SELECT * FROM (
  SELECT * FROM TSKGIAF01 ORDER BY 업로드일시 DESC
) WHERE ROWNUM <= #{limit}

SELECT * FROM (
  SELECT a.*, ROWNUM RN FROM (
    SELECT * FROM TSKGIAF01
    WHERE 기관명 LIKE '%' || #{keyword} || '%'
    ORDER BY 업로드일시 DESC
  ) a WHERE ROWNUM <= #{offset} + #{limit}
) WHERE RN > #{offset}
